/* two picture icons, used as they come (free icons from flaticon.com, credited in Settings > About) */
const SPACE_PICS = {movies:'data:image/png;base64,',
  netflix:'data:image/png;base64,',
  avengers:'data:image/png;base64,'};
const spIcon = sp => {
  const k = sp && sp.icon;
  if (k && SPACE_PICS[k]) return h('span', {class:'spico pic ' + k, 'aria-hidden':'true'}, h('img', {src:SPACE_PICS[k], alt:'', draggable:'false'}));
  const svg = k && SPACE_ICONS[k];
  if (!svg) return document.createTextNode((sp && sp.emoji) || '📺');
  const s = h('span', {class:'spico', 'aria-hidden':'true'}); s.innerHTML = svg; return s;
};
/* the pre-installed spaces get their icon (only if their emoji was never changed), and AIO becomes Cinema.
   Written without a sync stamp: every device does it for itself, so a new device never overwrites the account's spaces */
const SP_ICON_DEF = {aio:['movies', '🌐', '🍿'], netflix:['netflix', '🍿', '📺'], disney:['castle', '🏰', '🏰'], anime:['naruto', '🍥', '🍥'], marvel:['avengers', '🦸', '🦸'], kids:['bear', '🧸', '🧸']};
(() => { try {
  if (localStorage.getItem('streamlet.spIcons1')) return;
  let ch = false;
  for (const sp of spaces) {
    const d = SP_ICON_DEF[sp.id]; if (!d) continue;
    if (!sp.icon && sp.emoji === d[1]) { sp.icon = d[0]; sp.emoji = d[2]; ch = true; }
    if (sp.id === 'aio' && sp.name === 'AIO') { sp.name = 'Cinema'; ch = true; }
  }
  if (ch) try { localStorage.setItem('streamlet.spaces2', JSON.stringify(spaces)); } catch {}
  try { localStorage.setItem('streamlet.spIcons1', '1'); } catch {}
  } catch {}
})();
(() => { try {                                                             // v231: Netflix and Marvel switch to the picture icons
  if (localStorage.getItem('streamlet.spIcons2')) return;
  let ch = false;
  for (const sp of spaces) {
    if (sp.id === 'netflix' && sp.icon === 'tv') { sp.icon = 'netflix'; ch = true; }
    if (sp.id === 'marvel' && sp.icon === 'hero') { sp.icon = 'avengers'; ch = true; }
  }
  if (ch) localStorage.setItem('streamlet.spaces2', JSON.stringify(spaces));
  localStorage.setItem('streamlet.spIcons2', '1');
} catch {} })();
(() => { try {                                                             // v234: Cinema switches to its picture icon
  if (localStorage.getItem('streamlet.spIcons3')) return;
  let ch = false;
  for (const sp of spaces) if (sp.id === 'aio' && sp.icon === 'cinema') { sp.icon = 'movies'; ch = true; }
  if (ch) localStorage.setItem('streamlet.spaces2', JSON.stringify(spaces));
  localStorage.setItem('streamlet.spIcons3', '1');
} catch {} })();
